113: 	// A completed Review Task without a recorded verdict is a void round. Settle
114: 	// it here as well as on admission so crashes and older transitions cannot
115: 	// leave the active-round guard stuck indefinitely.
116: 	if _, err := tx.ExecContext(ctx, `UPDATE review_rounds SET status='void'
117: WHERE ship_task_id=? AND status='admitted'
118:   AND EXISTS (SELECT 1 FROM tasks r WHERE r.id=review_rounds.review_task_id AND r.state IN ('failed','lost','reported','torn-down'))
119:   AND NOT EXISTS (SELECT 1 FROM review_verdicts v WHERE v.task_id=review_rounds.review_task_id)`, admission.ChangeTaskID); err != nil {
120: 		return err
121: 	}
122: 	var active bool
123: 	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(
124: SELECT 1 FROM review_rounds rr JOIN tasks r ON r.id=rr.review_task_id
125: WHERE rr.ship_task_id=? AND rr.status='admitted'
126:   AND r.state NOT IN ('failed','lost','reported','torn-down'))`, admission.ChangeTaskID).Scan(&active); err != nil {
127: 		return err
128: 	}
129: 	if active {
130: 		return ErrReviewRoundActive
131: 	}
132: 	var used int
133: 	if err := tx.QueryRowContext(ctx, `SELECT COUNT(DISTINCT round) FROM review_rounds WHERE ship_task_id=? AND status='verdict'`, admission.ChangeTaskID).Scan(&used); err != nil {
134: 		return err
135: 	}
136: 	if admission.Round != used+1 {
137: 		return ErrReviewRoundNumber
138: 	}
139: 	seen := make(map[string]bool, len(admission.Bindings))
140: 	anyNewHead := false
141: 	for _, binding := range admission.Bindings {
142: 		if binding.ChangeTaskID != admission.ChangeTaskID || binding.Round != admission.Round || binding.Repository == "" || seen[binding.Repository] || binding.Status != "admitted" || binding.Verdict != "" {
143: 			return fmt.Errorf("invalid repository binding in review round admission")
144: 		}
145: 		seen[binding.Repository] = true
146: 		var unchanged bool
147: 		if err := tx.QueryRowContext(ctx, `SELECT EXISTS(
148: SELECT 1 FROM review_rounds WHERE ship_task_id=? AND repository=? AND status='verdict' AND head_sha=?
149: UNION ALL
150: SELECT 1 FROM review_carries WHERE ship_task_id=? AND repository=? AND to_head=?)`,
151: 			admission.ChangeTaskID, binding.Repository, binding.HeadSHA,
152: 			admission.ChangeTaskID, binding.Repository, binding.HeadSHA).Scan(&unchanged); err != nil {
153: 			return err
154: 		}
155: 		if !unchanged {
156: 			anyNewHead = true
157: 		}
158: 	}
159: 	var finalReview bool
160: 	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM review_cap_grants WHERE task_id=? AND round=?)`, admission.ChangeTaskID, admission.Round).Scan(&finalReview); err != nil {
161: 		return err
162: 	}
163: 	if finalReview {
164: 		var pending bool
165: 		if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM validation_fix_rounds r JOIN messages m ON m.id=r.message_id WHERE r.ship_task_id=? AND r.kind='review' AND m.status IN ('queued','claimed','interrupting','submitting','delivered') AND m.created_at>COALESCE((SELECT MAX(at) FROM signals WHERE task_id=? AND verb='done'),0))`, admission.ChangeTaskID, admission.ChangeTaskID).Scan(&pending); err != nil {
166: 			return err
167: 		}
168: 		if pending {
169: 			return ErrReviewRoundActive
170: 		}
171: 	}
172: 	if !anyNewHead && !finalReview {
173: 		return ErrReviewRoundUnchanged
174: 	}
175: 	if !admission.SharedRepairBudget && used >= admission.MaxRounds && !finalReview {
176: 		return ErrReviewRoundCap
177: 	}
178: 	return nil
179: }
